const express = require('express');
const { Pool } = require('pg');
const app = express();

app.use(express.json());

// Database connection pool
const pool = new Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  max: 20
});

// Unicode-aware username normalization for search
function normalizeUsername(input) {
  // NFC normalization to handle composed/decomposed forms
  // e.g., ñ (U+00F1) vs n + ̃ (U+006E U+0303)
  return input.normalize('NFC');
}

// Middleware: basic input length check
function validateInput(req, res, next) {
  const { username } = req.query;
  if (!username || username.length > 128) {
    return res.status(400).json({ error: 'Invalid username parameter' });
  }
  next();
}

// Search endpoint - finds users by normalized username
app.get('/api/users/search', validateInput, async (req, res) => {
  try {
    const rawUsername = req.query.username;

    // Normalize unicode before querying
    const normalized = normalizeUsername(rawUsername);

    // VULNERABILITY: After normalization, certain Unicode sequences
    // can produce SQL metacharacters. For example:
    // U+FF07 (fullwidth apostrophe ＇) normalizes differently across contexts
    // U+02BC (modifier letter apostrophe ʼ) may bypass pre-normalization checks
    // The query uses string interpolation after normalization
    const query = `SELECT id, username, email, display_name, created_at 
                   FROM users 
                   WHERE username ILIKE '%${normalized}%' 
                   OR display_name ILIKE '%${normalized}%'`;

    const result = await pool.query(query);

    res.json({
      count: result.rows.length,
      users: result.rows.map(row => ({
        id: row.id,
        username: row.username,
        displayName: row.display_name,
        email: row.email,
        memberSince: row.created_at
      }))
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Profile endpoint
app.get('/api/users/:id', async (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);
    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    const result = await pool.query(
      'SELECT id, username, email, display_name, bio, created_at FROM users WHERE id = $1',
      [userId]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(result.rows[0]);
  } catch (err) {
    console.error('Profile error:', err.message);
    res.status(500).json({ error: 'Failed to fetch profile' });
  }
});

// Admin data export (internal use)
app.get('/api/admin/export', async (req, res) => {
  try {
    const table = req.query.table || 'users';
    // Only allow specific tables
    const allowed = ['users', 'posts', 'comments'];
    if (!allowed.includes(table)) {
      return res.status(403).json({ error: 'Table not permitted' });
    }
    const result = await pool.query(`SELECT * FROM ${table} LIMIT 1000`);
    res.json(result.rows);
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Export failed' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`User service listening on port ${PORT}`);
});
